return $input.all().flatMap(item => {
  const data = item.json;
  const chunks = [];

  if (!data.semanticContent || typeof data.semanticContent !== "string") return [];

  const text = data.semanticContent
    .replace(/Project Name:.*\n/, "")
    .replace(/Document Name:.*\n/, "")
    .replace(/Document Type:.*\n/, "");

  // 1ÃƒÂ¯Ã‚Â¸Ã‚ÂÃƒÂ¢Ã†â€™Ã‚Â£ Split text into candidate lines
  const lines = text.split(/\n/g).map(l => l.trim()).filter(l => l);

  let currentSection = [];
  let sectionIndex = 0;
  let sectionTitle = "";

  // ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ TUNED: Increased from 1500 chars / 200 overlap
  // 10000 chars ÃƒÂ¢Ã¢â‚¬Â°Ã‹â€  2500 tokens ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â better for enterprise documents with cross-references
  // 2000 chars overlap ÃƒÂ¢Ã¢â‚¬Â°Ã‹â€  500 tokens ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â enough to maintain context continuity across chunks
  const chunkSize = 10000;
  const overlap = 2000;

  // ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ NEW: Minimum chunk size guard ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â skip chunks too small to be meaningful
  // Tiny chunks (e.g. a lone heading) create noise in the vector store
  const minChunkSize = 200;

  const headingRegex =
    /^(\d+(\.\d+)*\s+.*|[A-Z]{1,3}-\d+\s+.*|[A-Z][A-Za-z\s]{3,50}:?)$/;

  // ÃƒÂ°Ã…Â¸Ã¢â‚¬ÂÃ‚Â¥ Helper ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ Detect imageId from chunk text (UNCHANGED)
  function extractImageId(text) {
    const match = text.match(/Image ID:\s*(.+)/i);
    return match ? match[1].trim() : null;
  }

  function buildChunks(sectionText) {
    const result = [];

    // ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ NEW: If the entire section fits in one chunk, emit it as-is (no loop needed)
    // This preserves full section context and avoids unnecessary splitting
    if (sectionText.length <= chunkSize) {
      const imageId = extractImageId(sectionText);

      let contentSource = "text";
      if (data.contentMode === "image-only") {
        contentSource = "image";
      } else if (data.contentMode === "hybrid") {
        contentSource = imageId ? "image" : "text";
      }

      const project = data.projectName || "unknown";
      const docType = data.docType || "unknown";
      const compositeKey = `${project}|${docType}|${contentSource}`;

      // ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ NEW: Skip chunks that are too small to be meaningful
      if (sectionText.trim().length >= minChunkSize) {
        result.push({
          json: {
            pageContent: sectionText,
            metadata: {
              project,
              jobId: data.jobId,
              status: data.status,
              fileName: data.fileName || "unknown",
              fileType: data.fileType || "unknown",
              documentId: data.documentId || "unknown",
              docType,
              pageCount: data.pageCount || 0,
              contentMode: data.contentMode || "unknown",
              containsImages: data.containsImages || false,
              containsText: data.containsText || false,
              documentCategory: data.fileType || "unknown",
              sectionTitle: sectionTitle || `Section ${sectionIndex}`,
              sectionIndex,
              structuralType: "logical_section",
              chunkIndex: 0,
              imageId: imageId || null,
              contentSource,
              compositeKey,
              projectId: data.projectId || null,
              requestedBy: data.requestedBy || null,
              settingsVersion: data.settingsVersion || null,
              environment: data.environmentKey || 'local',
              chromaCollection: data.configSnapshot?.chroma?.collection || 'qa-chunks-batches'
            }
          }
        });
      }

      return result;
    }

    // ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ TUNED: Same sliding window loop, but now with larger chunkSize + overlap
    // Also added minChunkSize guard to skip the final tiny trailing chunk
    for (let i = 0; i < sectionText.length; i += (chunkSize - overlap)) {
      const chunkText = sectionText.slice(i, i + chunkSize);

      // ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ NEW: Skip the final chunk if it's too small (trailing fragment)
      // This happens when the last window has very little remaining text
      if (chunkText.trim().length < minChunkSize) break;

      const imageId = extractImageId(chunkText);

      let contentSource = "text";
      if (data.contentMode === "image-only") {
        contentSource = "image";
      } else if (data.contentMode === "hybrid") {
        contentSource = imageId ? "image" : "text";
      }

      const project = data.projectName || "unknown";
      const docType = data.docType || "unknown";
      const compositeKey = `${project}|${docType}|${contentSource}`;

      result.push({
        json: {
          pageContent: chunkText,
          metadata: {
            project,
            jobId: data.jobId,
            status: data.status,
            fileName: data.fileName || "unknown",
            fileType: data.fileType || "unknown",
            documentId: data.documentId || "unknown",
            docType,
            pageCount: data.pageCount || 0,
            contentMode: data.contentMode || "unknown",
            containsImages: data.containsImages || false,
            containsText: data.containsText || false,
            documentCategory: data.fileType || "unknown",
            sectionTitle: sectionTitle || `Section ${sectionIndex}`,
            sectionIndex,
            structuralType: "logical_section",
            chunkIndex: Math.floor(i / (chunkSize - overlap)),
            imageId: imageId || null,
            contentSource,
            compositeKey,
              projectId: data.projectId || null,
              requestedBy: data.requestedBy || null,
              settingsVersion: data.settingsVersion || null,
              environment: data.environmentKey || 'local',
              chromaCollection: data.configSnapshot?.chroma?.collection || 'qa-chunks-batches'
            }
        }
      });
    }

    return result;
  }

  lines.forEach(line => {
    if (headingRegex.test(line)) {
      if (currentSection.length) {
        const sectionText = currentSection.join("\n").trim();
        if (sectionText) {
          chunks.push(...buildChunks(sectionText));
        }
      }
      sectionIndex++;
      sectionTitle = line;
      currentSection = [line];
    } else {
      currentSection.push(line);
    }
  });

  // Last section (UNCHANGED)
  if (currentSection.length) {
    const sectionText = currentSection.join("\n").trim();
    if (sectionText) {
      chunks.push(...buildChunks(sectionText));
    }
  }

  return chunks;
});

