const visionOutputs = $input.all();
const originalItems = $items("Prepare Vision Payload");

function readUsage(json) {
  const usage =
    json.usage ||
    json.response?.usage ||
    json.output?.usage ||
    json.output?.[0]?.usage ||
    json.llmUsage ||
    {};

  const inputTokens =
    Number(usage.input_tokens) ||
    Number(usage.prompt_tokens) ||
    Number(usage.inputTokens) ||
    Number(usage.promptTokens) ||
    0;

  const outputTokens =
    Number(usage.output_tokens) ||
    Number(usage.completion_tokens) ||
    Number(usage.outputTokens) ||
    Number(usage.completionTokens) ||
    0;

  return { inputTokens, outputTokens };
}

const results = [];

for (const vision of visionOutputs) {
  const rawText =
    vision.json.output?.[0]?.content?.[0]?.text ||
    vision.json.output_text ||
    '';

  const imageDescription = rawText.trim();
  const pairedIndex = vision.pairedItem?.item;
  const original = originalItems[pairedIndex];

  if (!original) continue;

  const usage = readUsage(vision.json || {});
  const estimatedOutputTokens = usage.outputTokens || Math.ceil(imageDescription.length / 4);
  const meta = original.json;

  results.push({
    json: {
      projectName: meta.projectName,
      status: meta.status,
      jobId: meta.jobId,
      imageIndex: meta.imageIndex,
      imageId: meta.imageId,
      imageFileName: meta.imageFileName,
      parentFileName: meta.parentFileName,
      imageDescription,
      totalImagesInDocument: meta.totalImagesInDocument || null,
      imageLimitApplied: meta.imageLimitApplied || false,
      visionTokensInput: usage.inputTokens,
      visionTokensOutput: estimatedOutputTokens,
      visionTokensTotal: usage.inputTokens + estimatedOutputTokens,
      visionUsageEstimated: !usage.inputTokens && !usage.outputTokens
    }
  });
}

return results;

const originalDocs = $items("Extract Text + Image");
const visionResults = $input.all();

const visionMap = {};
const usageMap = {};

for (const item of visionResults) {
  const { imageId, imageDescription } = item.json;
  visionMap[imageId] = imageDescription;
  usageMap[imageId] = {
    input: Number(item.json.visionTokensInput) || 0,
    output: Number(item.json.visionTokensOutput) || 0,
    total: Number(item.json.visionTokensTotal) || 0,
    estimated: Boolean(item.json.visionUsageEstimated)
  };
}

const VISION_INPUT_PER_TOKEN = 0.15 / 1_000_000;
const VISION_OUTPUT_PER_TOKEN = 0.60 / 1_000_000;

return originalDocs.map(doc => {
  const data = doc.json;

  if (!data.images || data.images.length === 0) {
    return {
      json: {
        ...data,
        visionTokensInput: 0,
        visionTokensOutput: 0,
        visionTokensTotal: 0,
        visionCostUsd: 0,
        visionUsageEstimated: false
      }
    };
  }

  let visionTokensInput = 0;
  let visionTokensOutput = 0;
  let visionUsageEstimated = false;

  const updatedImages = data.images.map(img => {
    const usage = usageMap[img.imageId] || {};
    visionTokensInput += Number(usage.input) || 0;
    visionTokensOutput += Number(usage.output) || 0;
    visionUsageEstimated = visionUsageEstimated || Boolean(usage.estimated);
    return {
      imageFileName: img.fileName,
      imageId: img.imageId,
      imageDescription: visionMap[img.imageId] || null,
      visionTokensInput: Number(usage.input) || 0,
      visionTokensOutput: Number(usage.output) || 0,
      visionTokensTotal: Number(usage.total) || 0,
      visionUsageEstimated: Boolean(usage.estimated)
    };
  });

  const visionCostUsd =
    (visionTokensInput * VISION_INPUT_PER_TOKEN) +
    (visionTokensOutput * VISION_OUTPUT_PER_TOKEN);

  return {
    json: {
      ...data,
      images: updatedImages,
      visionTokensInput,
      visionTokensOutput,
      visionTokensTotal: visionTokensInput + visionTokensOutput,
      visionCostUsd: Number(visionCostUsd.toFixed(6)),
      visionUsageEstimated
    }
  };
});

return $input.all().map(item => {
  const d = item.json;

  let combined = '';

  combined += `Project Name: ${d.projectName}\n`;
  combined += `Document Name: ${d.fileName}\n`;
  combined += `Document Type: ${d.fileType}\n\n`;

  if (d.rawText && d.rawText.trim().length > 0) {
    combined += '===== DOCUMENT TEXT =====\n';
    combined += d.rawText.trim() + '\n\n';
  }

  if (d.images && d.images.length > 0) {
    const validImages = d.images.filter(img => img.imageDescription);

    if (validImages.length > 0) {
      combined += '===== IMAGE-DERIVED INSIGHTS =====\n\n';

      for (const img of validImages) {
        combined += `--- IMAGE CONTEXT START ---\n`;
        combined += `Image Name: ${img.imageFileName}\n`;
        combined += `Image ID: ${img.imageId}\n\n`;
        combined += `Extracted Insights:\n`;
        combined += img.imageDescription + '\n\n';
        combined += `--- IMAGE CONTEXT END ---\n\n`;
      }
    }
  }

  return {
    json: {
      projectName: d.projectName,
      status: d.status,
      jobId: d.jobId,
      fileName: d.fileName,
      fileType: d.fileType,
      pageCount: d.pageCount,
      docType: d.docType,
      documentId: d.documentId,
      contentMode: d.contentMode,
      containsText: d.containsText,
      containsImages: d.containsImages,
      semanticContent: combined.trim(),
      visionTokensInput: Number(d.visionTokensInput) || 0,
      visionTokensOutput: Number(d.visionTokensOutput) || 0,
      visionTokensTotal: Number(d.visionTokensTotal) || 0,
      visionCostUsd: Number(d.visionCostUsd) || 0,
      visionUsageEstimated: Boolean(d.visionUsageEstimated),
      projectId: d.projectId || $('When Executed by Another Workflow').first().json.projectId || $('When Executed by Another Workflow').first().json.project_id || null,
      requestedBy: d.requestedBy || $('When Executed by Another Workflow').first().json.requestedBy || $('When Executed by Another Workflow').first().json.requested_by || null,
      settingsVersion: d.settingsVersion || $('When Executed by Another Workflow').first().json.settingsVersion || $('When Executed by Another Workflow').first().json.settings_version || null,
      configSnapshot: d.configSnapshot || $('When Executed by Another Workflow').first().json.configSnapshot || $('When Executed by Another Workflow').first().json.config_snapshot || {},
      environmentKey: (d.configSnapshot || $('When Executed by Another Workflow').first().json.configSnapshot || $('When Executed by Another Workflow').first().json.config_snapshot || {}).environment?.key || d.environment || 'local'
    }
  };
});

